WITH joined AS (SELECT src.id, src.order_id, src.product_id, src.quantity, src.unit_price, p.cost, p.stock_qty, p.product_name FROM order_items src LEFT JOIN products p ON src.product_id <=> p.id) SELECT s.id, s.order_id, s.product_id, s.quantity, s.unit_price, s.cost, s.stock_qty, s.product_name, CASE WHEN product_name RLIKE '^(wireless mouse|Yoga Mat)$' THEN 'GROUP_A' WHEN product_name RLIKE '^(Laptop Pro 14|USB-C Hub)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS product_name_zone, (SELECT AVG(i2.quantity) FROM inventory i2 WHERE i2.product_id = s.product_id) AS avg_inventory_quantity FROM joined s ORDER BY product_name_zone DESC;
